import vm from'node:vm';import fs from'node:fs';import assert from'node:assert/strict';
export async function verify(){const checks=[],dir='public/',js=fs.readdirSync(dir).filter(f=>f.endsWith('.js'));for(const f of js)new vm.Script(fs.readFileSync(dir+f,'utf8'),{filename:f});checks.push('All JavaScript parses');const ctx=vm.createContext({window:{}});for(const f of['words.js','passages-1.js','passages-2.js','passages-3.js'])vm.runInContext(fs.readFileSync(dir+f,'utf8'),ctx);assert.equal(ctx.window.PASSAGES.length,30);assert.equal(new Set(ctx.window.PASSAGES.map(p=>p.rank)).size,30);for(const p of ctx.window.PASSAGES){const[a,b]=p.range.match(/\d+/g).map(Number);assert(a>=1&&b>=a&&p.surahNo>=1&&p.surahNo<=114);}checks.push('30 unique valid passage ranges');assert.deepEqual(Object.keys(ctx.window.WORDS).sort(),['bn','en','ja']);const html=fs.readFileSync(dir+'index.html','utf8');const keys=new Set([...html.matchAll(/data-i18n="([^"]+)"/g)].map(m=>m[1]));for(const f of js)for(const m of fs.readFileSync(dir+f,'utf8').matchAll(/Q\.t\('([^']+)'\)/g))keys.add(m[1]);for(const lang of['en','bn','ja'])for(const k of keys)assert(ctx.window.WORDS[lang][k],lang+' missing '+k);checks.push('All static UI keys translated in English Bangla Japanese');for(const m of html.matchAll(/(?:src|href)="(\/[^"?#]*)"/g))assert(fs.existsSync(dir+m[1].slice(1)),m[1]);assert(!html.includes('__SITE__'));assert(!html.includes('data-lang="hi"'));checks.push('Local assets and metadata references exist');
const events={},map=new Map();const cache={addAll:async paths=>{for(const p of paths){assert(fs.existsSync(dir+(p==='/'?'index.html':p.slice(1))),p);map.set(p,new Response(p));}},match:async p=>map.get(p)?.clone()};const context={self:{addEventListener:(n,f)=>events[n]=f,clients:{claim:async()=>{}}},location:{origin:'https://test.invalid'},caches:{open:async()=>cache,keys:async()=>['fq-shell-old','unrelated'],delete:async n=>assert.equal(n,'fq-shell-old')},URL,Response,Headers,fetch:async()=>{throw Error('Offline test');}};vm.runInNewContext(fs.readFileSync(dir+'sw.js','utf8'),context);let done;events.install({waitUntil:p=>done=p});await done;checks.push('Every service-worker precache path exists');events.activate({waitUntil:p=>done=p});await done;checks.push('Worker cleanup preserves unrelated cache');events.fetch({request:{url:'https://test.invalid/',method:'GET',mode:'navigate',headers:new Headers()},respondWith:p=>done=p});assert.equal(await(await done).text(),'/index.html');checks.push('Worker offline navigation returns cached shell (VM test)');let intercepted=false;for(const url of['https://test.invalid/?code=TEST','https://example.supabase.co/rest/v1/backups'])events.fetch({request:{url,method:'GET',mode:'navigate',headers:new Headers({Authorization:'Bearer TEST'})},respondWith:()=>intercepted=true});assert.equal(intercepted,false);checks.push('Auth callbacks and cross-origin private requests are excluded');return checks;}
